  const repo = fixture({ baseFiles: { 'test/real.test.js': UTIL_V2 } });
  fs.symlinkSync('real.test.js', path.join(repo.work, 'test/link.test.js'));
  repo.git('add', '-A'); repo.git('commit', '-q', '-m', 'link'); repo.git('push', '-q', 'origin', 'HEAD:main');
  commit(repo, { 'test/link.test.js': null });
  const r = lanes(repo);
  expect(r.check.code).toBe('PREGATE_NO_LANE');
  expect(r.check.detail).toContain('test/link.test.js');
});
